import { useQuery } from '@tanstack/react-query';
import { api } from './api';

export interface SavedSql {
  id: string; name: string; description: string; owner: string; visibility: 'private' | 'team'; version: number; created_at: string; updated_at: string;
  /** sql: Custom SQL text. builder: an Assets / Vulnerabilities query (typed spec; SQL is generated by the server) */
  kind: 'sql' | 'builder';
  sql: string;
  entity?: 'assets' | 'vulnerabilities';
  payload?: { tree: any; columns: string[] | null; sort: any; options: any; mode?: 'rows' | 'summary'; summary?: any };
}
export const SavedApi = {
  me: () => api<{ user: string }>('/api/saved/me').then((r) => r.user),
  list: () => api<{ queries: SavedSql[] }>('/api/saved').then((r) => r.queries),
  create: (b: { name: string; description?: string; visibility?: string; kind?: 'sql' | 'builder'; sql?: string; entity?: string; payload?: unknown }) => api<SavedSql>('/api/saved', { method: 'POST', json: b }),
  update: (id: string, b: Partial<Pick<SavedSql, 'name' | 'description' | 'visibility' | 'sql' | 'payload'>>) => api<SavedSql>(`/api/saved/${id}`, { method: 'PUT', json: b }),
  remove: (id: string) => api<{ ok: true }>(`/api/saved/${id}`, { method: 'DELETE' }),
  duplicate: (id: string) => api<SavedSql>(`/api/saved/${id}/duplicate`, { method: 'POST', json: {} }),
  sqlOf: (id: string) => api<{ sql: string; inline: string }>(`/api/saved/${id}/sql`),
  versions: (id: string) => api<{ versions: { version: number; updated_at: string }[] }>(`/api/saved/${id}/versions`).then((r) => r.versions),
  rollback: (id: string, version: number) => api<SavedSql>(`/api/saved/${id}/rollback`, { method: 'POST', json: { version } }),
};
export const kindLabel = (q: Pick<SavedSql, 'kind' | 'entity'>) => (q.kind === 'builder' ? (q.entity === 'assets' ? 'Assets' : 'Vulnerabilities') : 'SQL');
export const useSavedSql = () => useQuery({ queryKey: ['saved-sql'], queryFn: SavedApi.list, staleTime: 30_000, retry: false });
export const useMe = () => useQuery({ queryKey: ['saved-me'], queryFn: SavedApi.me, staleTime: Infinity, retry: false });
